-- manifest: **Visualizações de fábrica das Oportunidades.** Cria, em cada organização, as abas Conversão, Origem, Vendas e pagamentos, Perdas e Quadro de conversão (colunas e filtros escolhidos para trabalhar o lead e para analisar origem, vendas e perdas), sem duplicar as que já existem pelo nome. Só dados; nenhuma tabela muda.

-- Visualizações de fábrica das Oportunidades (por organização, só as que ainda não existem pelo nome).
-- created_by nulo = da organização (quem é manager+ edita). Ordem: Conversão, Origem, Vendas, Perdas, Quadro.
do $visoes$
declare
  o record;
  v record;
begin
  for o in select id from public.organizations loop
    for v in
      select * from (values
    ('Conversão', 'tabela', $cfg${"ordem":["nome","ligar","inbox","acao","cliente","telefone","etapa","responsavel","radar","sem-resposta","op-tempo-na-etapa","op-ultima-atividade","tentativas","resultado-rapido","proxima-acao","proxima-acao-em","cadencia","previsao","previsto","campanha","whatsapp","instagram","entrou-no-funil","produtos","pago","op-interesse","origem","anuncio","lp","posicionamento","op-utm-fonte","op-utm-meio","op-utm-campanha","op-utm-termo","op-utm-conteudo","op-atribuido-em","op-criado-por","op-retomada","op-etapa-da-perda","op-motivo-da-perda","op-dias-ate-perder","op-tags"],"visiveis":{"nome":true,"cliente":true,"telefone":true,"etapa":true,"campanha":false,"responsavel":true,"radar":true,"sem-resposta":true,"op-tempo-na-etapa":true,"op-ultima-atividade":true,"tentativas":true,"resultado-rapido":true,"ligar":true,"whatsapp":false,"instagram":false,"inbox":true,"acao":true,"proxima-acao":true,"proxima-acao-em":true,"cadencia":true,"previsao":true,"entrou-no-funil":false,"produtos":false,"pago":false,"op-interesse":false,"previsto":true,"origem":false,"anuncio":false,"lp":false,"posicionamento":false,"op-utm-fonte":false,"op-utm-meio":false,"op-utm-campanha":false,"op-utm-termo":false,"op-utm-conteudo":false,"op-atribuido-em":false,"op-criado-por":false,"op-retomada":false,"op-etapa-da-perda":false,"op-motivo-da-perda":false,"op-dias-ate-perder":false,"op-tags":false},"filtros":[{"campo":"sem-resposta","operador":"preenchido"}],"ordenacao":[{"campo":"radar","direcao":"asc"},{"campo":"sem-resposta","direcao":"desc"}]}$cfg$::jsonb),
    ('Origem', 'tabela', $cfg${"ordem":["nome","cliente","campanha","origem","anuncio","lp","posicionamento","op-utm-fonte","op-utm-meio","op-utm-campanha","op-utm-termo","op-utm-conteudo","entrou-no-funil","op-atribuido-em","op-criado-por","responsavel","op-retomada","etapa","pago","telefone","radar","sem-resposta","op-tempo-na-etapa","op-ultima-atividade","tentativas","resultado-rapido","ligar","whatsapp","instagram","inbox","acao","proxima-acao","proxima-acao-em","cadencia","previsao","produtos","op-interesse","previsto","op-etapa-da-perda","op-motivo-da-perda","op-dias-ate-perder","op-tags"],"visiveis":{"nome":true,"cliente":true,"telefone":false,"etapa":true,"campanha":true,"responsavel":true,"radar":false,"sem-resposta":false,"op-tempo-na-etapa":false,"op-ultima-atividade":false,"tentativas":false,"resultado-rapido":false,"ligar":false,"whatsapp":false,"instagram":false,"inbox":false,"acao":false,"proxima-acao":false,"proxima-acao-em":false,"cadencia":false,"previsao":false,"entrou-no-funil":true,"produtos":false,"pago":true,"op-interesse":false,"previsto":false,"origem":true,"anuncio":true,"lp":true,"posicionamento":true,"op-utm-fonte":true,"op-utm-meio":true,"op-utm-campanha":true,"op-utm-termo":true,"op-utm-conteudo":true,"op-atribuido-em":true,"op-criado-por":true,"op-retomada":true,"op-etapa-da-perda":false,"op-motivo-da-perda":false,"op-dias-ate-perder":false,"op-tags":false}}$cfg$::jsonb),
    ('Vendas e pagamentos', 'tabela', $cfg${"ordem":["nome","cliente","campanha","produtos","etapa","pago","op-interesse","previsto","previsao","entrou-no-funil","responsavel","telefone","radar","sem-resposta","op-tempo-na-etapa","op-ultima-atividade","tentativas","resultado-rapido","ligar","whatsapp","instagram","inbox","acao","proxima-acao","proxima-acao-em","cadencia","origem","anuncio","lp","posicionamento","op-utm-fonte","op-utm-meio","op-utm-campanha","op-utm-termo","op-utm-conteudo","op-atribuido-em","op-criado-por","op-retomada","op-etapa-da-perda","op-motivo-da-perda","op-dias-ate-perder","op-tags"],"visiveis":{"nome":true,"cliente":true,"telefone":false,"etapa":true,"campanha":true,"responsavel":true,"radar":false,"sem-resposta":false,"op-tempo-na-etapa":false,"op-ultima-atividade":false,"tentativas":false,"resultado-rapido":false,"ligar":false,"whatsapp":false,"instagram":false,"inbox":false,"acao":false,"proxima-acao":false,"proxima-acao-em":false,"cadencia":false,"previsao":true,"entrou-no-funil":true,"produtos":true,"pago":true,"op-interesse":true,"previsto":true,"origem":false,"anuncio":false,"lp":false,"posicionamento":false,"op-utm-fonte":false,"op-utm-meio":false,"op-utm-campanha":false,"op-utm-termo":false,"op-utm-conteudo":false,"op-atribuido-em":false,"op-criado-por":false,"op-retomada":false,"op-etapa-da-perda":false,"op-motivo-da-perda":false,"op-dias-ate-perder":false,"op-tags":false}}$cfg$::jsonb),
    ('Perdas', 'tabela', $cfg${"ordem":["nome","cliente","campanha","op-etapa-da-perda","op-motivo-da-perda","responsavel","op-dias-ate-perder","entrou-no-funil","telefone","etapa","radar","sem-resposta","op-tempo-na-etapa","op-ultima-atividade","tentativas","resultado-rapido","ligar","whatsapp","instagram","inbox","acao","proxima-acao","proxima-acao-em","cadencia","previsao","produtos","pago","op-interesse","previsto","origem","anuncio","lp","posicionamento","op-utm-fonte","op-utm-meio","op-utm-campanha","op-utm-termo","op-utm-conteudo","op-atribuido-em","op-criado-por","op-retomada","op-tags"],"visiveis":{"nome":true,"cliente":true,"telefone":false,"etapa":false,"campanha":true,"responsavel":true,"radar":false,"sem-resposta":false,"op-tempo-na-etapa":false,"op-ultima-atividade":false,"tentativas":false,"resultado-rapido":false,"ligar":false,"whatsapp":false,"instagram":false,"inbox":false,"acao":false,"proxima-acao":false,"proxima-acao-em":false,"cadencia":false,"previsao":false,"entrou-no-funil":true,"produtos":false,"pago":false,"op-interesse":false,"previsto":false,"origem":false,"anuncio":false,"lp":false,"posicionamento":false,"op-utm-fonte":false,"op-utm-meio":false,"op-utm-campanha":false,"op-utm-termo":false,"op-utm-conteudo":false,"op-atribuido-em":false,"op-criado-por":false,"op-retomada":false,"op-etapa-da-perda":true,"op-motivo-da-perda":true,"op-dias-ate-perder":true,"op-tags":false},"filtros":[{"campo":"op-motivo-da-perda","operador":"preenchido"}]}$cfg$::jsonb),
    ('Quadro de conversão', 'kanban', $cfg${"ordem":["nome","cliente","telefone","responsavel","previsto","radar","proxima-acao","proxima-acao-em","op-tempo-na-etapa","op-tags","etapa","campanha","sem-resposta","op-ultima-atividade","tentativas","resultado-rapido","ligar","whatsapp","instagram","inbox","acao","cadencia","previsao","entrou-no-funil","produtos","pago","op-interesse","origem","anuncio","lp","posicionamento","op-utm-fonte","op-utm-meio","op-utm-campanha","op-utm-termo","op-utm-conteudo","op-atribuido-em","op-criado-por","op-retomada","op-etapa-da-perda","op-motivo-da-perda","op-dias-ate-perder"],"visiveis":{"nome":true,"cliente":true,"telefone":true,"etapa":false,"campanha":false,"responsavel":true,"radar":true,"sem-resposta":false,"op-tempo-na-etapa":true,"op-ultima-atividade":false,"tentativas":false,"resultado-rapido":false,"ligar":false,"whatsapp":false,"instagram":false,"inbox":false,"acao":false,"proxima-acao":true,"proxima-acao-em":true,"cadencia":false,"previsao":false,"entrou-no-funil":false,"produtos":false,"pago":false,"op-interesse":false,"previsto":true,"origem":false,"anuncio":false,"lp":false,"posicionamento":false,"op-utm-fonte":false,"op-utm-meio":false,"op-utm-campanha":false,"op-utm-termo":false,"op-utm-conteudo":false,"op-atribuido-em":false,"op-criado-por":false,"op-retomada":false,"op-etapa-da-perda":false,"op-motivo-da-perda":false,"op-dias-ate-perder":false,"op-tags":true}}$cfg$::jsonb)
      ) as t(nome, tipo, config)
    loop
      if not exists (
        select 1 from public.crm_saved_views
         where organization_id = o.id and screen_key = 'oportunidades' and name = v.nome
      ) then
        insert into public.crm_saved_views (organization_id, screen_key, name, type, config)
        values (o.id, 'oportunidades', v.nome, v.tipo, v.config);
      end if;
    end loop;
  end loop;
end
$visoes$;

notify pgrst, 'reload schema';
